	(257, 8972, 'EGCGBYATRA001', 'Yatra Prime E-Gift Card', 'Yatra Prime E-Gift Card', '{"price":"SLAB","type":"SLAB","min":"999","max":"999","denominations":["999"],"currency":{"code":"INR","symbol":"\\u20b9","numericCode":"356"},"cpg":[]}', 0, NULL, '{"price":"SLAB","type":"SLAB","min":"999","max":"999","denominations":["999"],"currency":{"code":"INR","symbol":"\\u20b9","numericCode":"356"},"cpg":[]}', 'DIGITAL', '0', '{"code":"INR","symbol":"\\u20b9","numericCode":"356"}', '356', '{"thumbnail":"https:\\/\\/giftbig.s3.amazonaws.com\\/microsite\\/product\\/EGCGBYATRA001\\/d\\/thumbnail\\/8972_microsite.jpg","mobile":"https:\\/\\/giftbig.s3.amazonaws.com\\/microsite\\/product\\/EGCGBYATRA001\\/d\\/mobile\\/8972_microsite.jpg","base":"https:\\/\\/giftbig.s3.amazonaws.com\\/microsite\\/product\\/EGCGBYATRA001\\/d\\/image\\/8972_microsite.jpg","small":"https:\\/\\/giftbig.s3.amazonaws.com\\/microsite\\/product\\/EGCGBYATRA001\\/d\\/small_image\\/8972_microsite.jpg"}', '{"link":"https:\\/\\/woohoo.app.link\\/e\\/1pOEqI3iKBb","content":"<p style=\\"text-align: left;\\"><\\/p>\\r\\n<ol>\\r\\n<li class=\\"ListParagraph1\\">EGV is valid for a period of 30 Days from the date of issue.<\\/li>\\r\\n<li class=\\"ListParagraph1\\">EGV can be redeemed only at&nbsp;<a href=\\"http:\\/\\/www.yatra.com\\/\\" target=\\"_blank\\">www.yatra.com<\\/a>.<\\/li>\\r\\n<li class=\\"ListParagraph1\\">EGV is valid for subscription of Yatra Prime membership<\\/li>\\r\\n<li class=\\"ListParagraph1\\">For subscribing the Yatra Prime membership online at&nbsp;<a href=\\"http:\\/\\/www.yatra.com\\/\\" target=\\"_blank\\">www.yatra.com<\\/a>, please follow the following steps:<\\/li>\\r\\n<\\/ol>\\r\\n<ul>\\r\\n<li class=\\"ListParagraph1\\">Reach to Yatra Prime Subscription&nbsp; Page for Subscription&nbsp; click on respective link&nbsp;<a href=\\"https:\\/\\/www.yatra.com\\/prime?utm_source=YTHPDESK&amp;utm_medium=banner&amp;utm_campaign=YATRAPRIME\\" target=\\"_blank\\">https:\\/\\/www.yatra.com\\/prime?utm_source=YTHPDESK&amp;utm_medium=banner&amp;utm_campaign=YATRAPRIME<\\/a><\\/li>\\r\\n<li class=\\"ListParagraph1\\">Enter your credentials and proceed to payment page.<\\/li>\\r\\n<li class=\\"ListParagraph1\\">On payment page, select &ldquo;Gift Voucher&rdquo; as your Payment Mode<\\/li>\\r\\n<li class=\\"ListParagraph1\\">Enter your unique code<\\/li>\\r\\n<li class=\\"ListParagraph1\\">Click on &ldquo;Redeem Gift Card&rdquo; and pay the balance amount with listed mode of payment.<\\/li>\\r\\n<\\/ul>\\r\\n<ol>\\r\\n<li>In case of any query:<\\/li>\\r\\n<\\/ol>\\r\\n<p>&eth;&nbsp;&nbsp;&nbsp;Alternatively you can also write to:&nbsp;<a href=\\"mailto:coepromoteam@yatra.com\\" target=\\"_blank\\">coepromoteam@yatra.com<\\/a>.<\\/p>\\r\\n<ol>\\r\\n<li>EGV is valid for&nbsp;ONE time transaction only, Balance amount will be forfeited.<\\/li>\\r\\n<li>EGVs are non-cumulative, i.e. 2 or more EGVs cannot be combined and used in single transaction.<\\/li>\\r\\n<li>Any applicable convenience fee\\/processing fee\\/excess tour cost\\/ government taxes shall be payable at the time of booking (Only if the package cost exceed the EGV value)<\\/li>\\r\\n<li>If an EGV is lost or stolen, Yatra will not be liable for replacement or Compensation.<\\/li>\\r\\n<li>This EGV cannot be clubbed with any other ongoing offer discount\\/cash back\\/promotion run by Yatra.com.&nbsp;<\\/li>\\r\\n<li>No additional Discount \\/ reduction in the price will be entertained other than the value mentioned on the EGVs.<\\/li>\\r\\n<li>Yatra.com is not liable to pay for any difference in fare\\/tariff between date of redemption&nbsp;request placement and date of using EGV during booking.<\\/li>\\r\\n<li>No change or cash can be taken in exchange of this EGV.<\\/li>\\r\\n<li>In case of cancellations, no refund will be processed for the amount paid by EGV.<\\/li>\\r\\n<li><span style=\\"text-decoration: underline;\\">All the terms and conditions of the EGV as given hereof and standard terms and conditions, user agreement, privacy policy (subject to change) of Yatra.com as mentioned on the website www.yatra.com and the terms and conditions of the respective airline\\/ hotel \\/resort\\/other service provider shall be applicable on the Customer.<\\/span><\\/li>\\r\\n<li>Any legal disputes, whatsoever regarding any aspect of the promotion shall be handled in the jurisdiction of the courts in Gurgaon, Haryana only.<\\/li>\\r\\n<li>This is for individual use only, Travel agents found using the card would lead to cancellation of booking and no refund would be made.<\\/li>\\r\\n<\\/ol>"}', '["7","8","50","131","288","315","607","608","610","689","690","692","797"]', NULL, 'true', '[]', 'false', '30 days Days from the date of activation', NULL, '[]', '[]', NULL, 'Yatra', '', 'a:9:{s:7:"barcode";a:1:{s:8:"encoding";N;}s:15:"redemptionTerms";a:0:{}s:4:"type";s:3:"clp";s:4:"code";s:33:"Yatra Prime Membership eGift Card";s:13:"erupi_purpose";N;s:16:"erupi_payer_type";N;s:16:"erupi_payee_type";N;s:24:"erupi_recurrence_pattern";N;s:14:"erupi_validity";N;}', 'a:7:{s:7:"enabled";b:1;s:15:"payment_methods";a:1:{i:0;s:3:"svc";}s:13:"account_types";a:2:{i:0;s:12:"BANK_ACCOUNT";i:1;s:3:"UPI";}s:17:"transaction_types";a:3:{i:0;s:4:"IMPS";i:1;s:4:"NEFT";i:2;s:3:"UPI";}s:21:"maximum_beneficiaries";s:0:"";s:28:"validate_terms_and_condition";s:0:"";s:10:"validation";a:3:{s:6:"amount";s:1:"1";s:16:"edit_beneficiary";b:1;s:18:"convenience_charge";s:0:"";}}', '[{"code":false}]', 'yatra-prime-e-gift-card', '999', '999', NULL, '2023-12-11 13:37:58', '2023-07-26T09:14:07+00:00', '2023-12-08T07:11:16+00:00', 330),
	(258, 9065, 'EGCGBAHJ001', 'Euphoria Jewellery E-Gift Card', 'A.Himanshu Jewelery Pvt. Ltd. was setup by the entrepreneurial initiatives by the managers of A.Himanshu & Co to go a stepfurther in servicing their diamond customers who wanted a tailor made end product rather than just the raw material. It’s a steptaken in the lines of supplying diamonds from the mines to the high street.Since its origin in 2004, A.Himanshu Jewelery Pvt.Ltd. has maintained a tradition of trust and service, leading the evolutionof the jewellery industry with unique energy and passion for the business.', '{"price":"RANGE","type":"RANGE","min":"1000","max":"49999","denominations":[],"currency":{"code":"INR","symbol":"\\u20b9","numericCode":"356"},"cpg":[]}', 0, NULL, '{"price":"RANGE","type":"RANGE","min":"1000","max":"49999","denominations":[],"currency":{"code":"INR","symbol":"\\u20b9","numericCode":"356"},"cpg":[]}', 'DIGITAL', '0', '{"code":"INR","symbol":"\\u20b9","numericCode":"356"}', '356', '{"thumbnail":"","mobile":"","base":"","small":""}', '{"link":"https:\\/\\/woohoo.app.link\\/e\\/qvq2X5C71Cb","content":"This e-Gift card is activated once issued.<br\\/>This e-Gift Card is valid for 1 year from the date of activation\\/issuance and it cannot be further re-validated.<br\\/>This e-Gift card is valid on all products and can be redeemed online at www.euphoriajewellery.in only.<br\\/>This e-Gift card is allowed for one-time redemption only.<br\\/>Any unused balance on the e-Gift card will not be refunded or credited.<br\\/>This e-Gift Card is non-encashable.<br\\/>Bearer is responsible if an e-Gift Card is lost, stolen, destroyed or used without permission.<br\\/>These terms & conditions are subject to change at any time, without any prior notice.<br\\/>If the value of the purchase is less than the value of the Gift card, the balance is non-refundable.<br\\/>Different Offers\\/vouchers cannot be combined."}', '["7","8","10","50","192","288","607","608","610","689","690","692","797"